const settings = $('Settings').first().json;
// A run at five past reads the whole hours before the hour, so each alert falls in exactly one hourly run, and an
// alert saved a moment after its created_at still lands in a window that has not run yet.
const HOUR = 3600000;
const end = Math.floor(Date.now() / HOUR) * HOUR;
const start = end - (Number(settings.hours_back) || 1) * HOUR;
const page = $input.first().json;
if (page.error) {
  const msg = String(page.error.message || '');
  let body = null;
  try { body = JSON.parse(msg.slice(msg.indexOf(' - ') + 3)); if (typeof body === 'string') body = JSON.parse(body); } catch (_) {}
  const e = body?.error || {}, status = Number(page.error.status || page.error.httpCode || msg.slice(0, 3)) || 0;
  if (status === 401 || e.gate === 'key' || e.code === 'insufficient_scope') throw new Error(`Arcmira didn't accept the API key (${e.code || status}). Pick a Header Auth credential named Authorization with the value "Bearer <your key>" in "Get monitor alerts from Arcmira" and "Get transcript from Arcmira".`);
  if (!status) throw new Error(`Couldn't reach Arcmira for the monitor's alerts. ${msg}`);
  throw new Error(`Arcmira refused the monitor's alerts (${e.code || (status === 429 ? 'rate_limited' : status)}). ${e.message || msg}${e.unlock?.url ? ` ${e.unlock.url}` : ''}`);
}
const alerts = page.alerts || [];
const seen = new Set();
const out = [];
for (const a of alerts) {
  // One alert row per delivery channel, so a moment sent by email and Slack shows up twice.
  const key = a.mention_id || `${a.video_id}:${a.tracker_id}`;
  const at = Date.parse(a.created_at);
  if (!a.video_id || seen.has(key) || !(at >= start && at < end)) continue;
  seen.add(key);
  out.push({ json: { video_id: a.video_id, name: a.tracker?.entity_name || '', display_name: a.tracker?.display_name || '', monitor: a.monitor?.name || '', alerted_at: a.created_at } });
}
return out;  // nothing new: the run ends quietly and posts nothing

// One alert at a time: the loop hands this node one transcript, and the alert it belongs to.
const m = $('One alert at a time').first()?.json;
if (!m?.video_id) throw new Error('The loop gave this node no alert. Connect "One alert at a time" (loop output) to "Get transcript from Arcmira".');
const t = $input.first().json;
const refusal = (e) => {
  const msg = String(e.message || '');
  let body = null;
  try { body = JSON.parse(msg.slice(msg.indexOf(' - ') + 3)); if (typeof body === 'string') body = JSON.parse(body); } catch (_) {}
  const status = Number(e.status || e.httpCode || msg.slice(0, 3)) || 0;
  // n8n rewrites a 429's message, so its code is lost; name it from the status.
  return { status, code: body?.error?.code || (status === 429 ? 'rate_limited' : ''), gate: body?.error?.gate || '', text: body?.error?.message || msg, unlock: body?.error?.unlock?.url || '' };
};
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const words = (s) => String(s || '').toLowerCase().match(/[a-z0-9]+/g) || [];
// A name counts only when whole words spell it: "Cloud flare" and "CLOUD-FLARE" are Cloudflare, "ramped" is not Ramp.
const spells = (ws, from, to, key) => {
  for (let a = from; a < to; a++) {
    let run = '';
    for (let b = a; b < ws.length && run.length < key.length; b++) run += ws[b];
    if (run === key) return true;
  }
  return false;
};
const clock = (s) => { s = Math.floor(s); const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), x = s % 60; return (h ? h + ':' + String(m).padStart(2, '0') : m) + ':' + String(x).padStart(2, '0'); };
// At most about 300 characters, kept around the mention [s, e) and cut at word boundaries.
const clip = (text, a, b, s, e, open = '', shut = '') => {
  let lead = open, tail = shut;
  if (b - a > 300) {
    let x = Math.max(a, Math.min(s - 100, b - 300)), y = Math.min(b, x + 300);
    if (x > a) { const k = text.indexOf(' ', x); if (k >= 0 && k < s) x = k + 1; lead = '…'; }
    if (y < b) { const k = text.lastIndexOf(' ', y); if (k >= e) y = k; tail = '…'; }
    a = x; b = y;
  }
  return lead + text.slice(a, b).trim() + tail;
};
// The whole sentence that holds the mention, joined across neighbouring transcript lines.
const sentence = (lines, i, key, said) => {
  const from = Math.max(0, i - 4);
  const parts = lines.slice(from, i + 5).map((l) => String(l.text || '').replace(/\s+/g, ' ').trim());
  const starts = [];
  let text = '';
  for (const p of parts) { starts.push(text ? text.length + 1 : 0); text += (text ? ' ' : '') + p; }
  const here = i - from;
  let s = starts[here], e = s + parts[here].length;
  // Place the name on the words that said it, from the named line on: its own words when the hit came from them,
  // otherwise the whole words that join to spell it.
  const spans = [...text.matchAll(/[a-z0-9]+/gi)].map((w) => [w.index, w.index + w[0].length, w[0].toLowerCase()]);
  for (let a = spans.findIndex(([x]) => x >= s); a >= 0 && a < spans.length; a++) {
    let run = '', b = a;
    if (said) { if (!said.every((w, k) => spans[a + k]?.[2] === w)) continue; b = a + said.length; run = key; }
    else while (b < spans.length && run.length < key.length) run += spans[b++][2];
    if (run === key) { s = spans[a][0]; e = spans[b - 1][1]; break; }
  }
  // A transcript without punctuation has no sentences, so quote the named line with one line either side, marked as cut.
  if (!/[.!?]|>>/.test(text)) {
    const a = starts[Math.max(0, here - 1)], b = here + 1 < parts.length ? starts[here + 1] + parts[here + 1].length : text.length;
    return clip(text, a, b, s, e, from + Math.max(0, here - 1) > 0 ? '…' : '', i + 2 < lines.length ? '…' : '');
  }
  // A sentence starts after . ! or ? and a space, or after a ">>" speaker change, and ends at the next of them.
  let a = -1;
  for (const m of text.matchAll(/[.!?]["')\]]*\s+|>>\s*/g)) { if (m.index + m[0].length > s) break; a = m.index + m[0].length; }
  const stop = /[.!?]["')\]]*(?=\s|$)|\s*>>/g;
  stop.lastIndex = e;
  const end = stop.exec(text);
  // With no boundary in reach, start one line back or stop one line on, and mark the cut.
  const from0 = a >= 0 ? a : starts[Math.max(0, here - 1)];
  const to = end ? end.index + (end[0].includes('>') ? 0 : end[0].length) : here + 1 < parts.length ? starts[here + 1] + parts[here + 1].length : text.length;
  return clip(text, from0, to, s, e, a >= 0 || from0 === 0 ? '' : '…', end || to === text.length ? '' : '…');
};
if (t.error) {
  const e = refusal(t.error);
  // A wrong key, a plan gate or an account out of credits fails every alert, so stop the run where n8n shows it.
  if (e.status === 401 || e.gate === 'key' || e.code === 'insufficient_scope') throw new Error(`Arcmira didn't accept the API key (${e.code || e.status}). Pick a Header Auth credential named Authorization with the value "Bearer <your key>" in "Get monitor alerts from Arcmira" and "Get transcript from Arcmira".`);
  if (e.status === 402) throw new Error(`Arcmira refused the transcript for credits (${e.code || 402}). ${e.text}${e.unlock ? ` ${e.unlock}` : ''}`);
  if (e.status === 403) throw new Error(`Arcmira refused the transcript (${e.code || 403}). ${e.text}${e.unlock ? ` ${e.unlock}` : ''}`);
}
const lines = Array.isArray(t.lines) ? t.lines : [];
const title = t.video?.title || 'a new video';
const channel = t.video?.channel_name || '';
const also = String($('Settings').first().json.also_match || '').split(',');
const wanted = [m.name, m.display_name, ...also].map((n) => ({ key: norm(n), parts: words(n) })).filter((x) => x.key.length >= 3);
// Each hit keeps the name it matched, so the quote and the link point at the same words. First, a name said in its
// own words ("Workday", "Hugging Face", even across two lines). Only when no line has that do joined words count
// ("Cloud flare" for Cloudflare), so "work day" said early never beats "Workday" said later. A transcript that mixes
// both counts only the first kind.
const says = (ws, to, parts) => { for (let a = 0; a < to; a++) if (parts.every((w, k) => ws[a + k] === w)) return true; return false; };
const pass = (match) => {
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    const here = words(lines[i].text), ws = [...here, ...words(lines[i + 1]?.text)];
    const hit = wanted.find((x) => match(ws, here.length, x));
    if (hit) out.push({ i, ...hit });
  }
  return out;
};
let hits = pass((ws, to, x) => says(ws, to, x.parts));
if (!hits.length) hits = pass((ws, to, x) => spells(ws, 0, to, x.key)).map((h) => ({ ...h, parts: null }));
// Transcripts misspell brand names ("Verscell" for Vercel). With no exact match, take the closest transcript
// word that starts with the name's first three letters, ends in its last letter and is at most two letters off.
let guess = '';
// Only a one-word name gets a close spelling: "versel" is Vercel, not proof that "Vercel v0" was said.
const target = /\s/.test(String(m.name || '').trim()) ? '' : norm(m.name);
if (!hits.length && target.length >= 5) {
  const limit = target.length >= 6 ? 2 : 1;
  const lev = (a, b) => { let prev = [...Array(b.length + 1).keys()]; for (let i = 1; i <= a.length; i++) { const cur = [i]; for (let j = 1; j <= b.length; j++) cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] !== b[j - 1]))); prev = cur; } return prev[b.length]; };
  let best = null;
  lines.forEach((l, i) => {
    for (const w of String(l.text || '').toLowerCase().match(/[a-z0-9]+/g) || []) {
      if (w.slice(0, 3) !== target.slice(0, 3) || w.slice(-1) !== target.slice(-1) || Math.abs(w.length - target.length) > limit) continue;
      const d = lev(w, target);
      if (d <= limit && (!best || d < best.d)) best = { d, w };
    }
  });
  if (best) {
    guess = best.w;
    lines.forEach((l, i) => { if (words(l.text).includes(guess)) hits.push({ i, key: guess, parts: [guess] }); });
  }
}
// A 200 can still carry `access`: the gate that withheld part of the transcript.
const withheld = t.access ? `${t.access.code || 'access'}${t.access.message ? `: ${t.access.message}` : ''}` : '';
const who = m.display_name || m.name || 'Your company';
const head = `*${who}* was mentioned on YouTube in *${title}*${channel ? ` (${channel})` : ''}`;
if (!hits.length) {
  const why = t.error ? `Arcmira couldn't read the transcript (${refusal(t.error).code || refusal(t.error).status || 'error'})`
    : withheld ? `Arcmira withheld part of the transcript (${withheld})` : "the transcript doesn't spell the name out";
  return [{ json: { found: false, text: `${head}\n_The monitor matched it, but ${why}._ <https://www.youtube.com/watch?v=${m.video_id}|Open the video>` } }];
}
const { i, key, parts } = hits[0];
const quote = sentence(lines, i, key, parts);
const at = Math.floor(lines[i].start);
const more = (hits.length > 1 ? ` · mentioned ${hits.length} times` : '') + (guess ? ` · the transcript spells it "${guess}"` : '')
  + (withheld ? ` · Arcmira withheld part of the transcript (${withheld})` : '');
return [{ json: { found: true, text: `${head}\n> ${quote}\n<https://www.youtube.com/watch?v=${m.video_id}&t=${at}s|Watch at ${clock(at)}>${more}` } }];
